const languageNames={en:'EN',ja:'JP',ko:'한국어',th:'ไทย','zh-Hans':'中文'};
const languageOrder=['en','ja','ko','th','zh-Hans'];
function languageFromNavigator(){const locale=(navigator.language||'en').toLowerCase();if(locale.startsWith('ja'))return 'ja';if(locale.startsWith('ko'))return 'ko';if(locale.startsWith('th'))return 'th';if(locale.startsWith('zh'))return 'zh-Hans';return 'en';}
function setLanguage(next,save=true){if(save){const route=next==='en'?'/':next==='zh-Hans'?'/zh-hans/':'/'+next+'/';if(location.pathname!==route){location.assign(route+location.hash);return;}}language=next;document.documentElement.lang=next==='zh-Hans'?'zh-Hans':next;document.querySelectorAll('[data-en][data-ja]').forEach(el=>{const source=el.dataset.en;el.innerHTML=next==='en'?source:(translations[next]?.[source]??(next==='ja'?el.dataset.ja:source));});copyStatus.textContent='';if(save){try{localStorage.setItem('fxxkup-language',next)}catch{}}if(carouselReady)updatePhotoLabels();refineIcons();}
const pageLanguage=({'ja':'ja','ko':'ko','th':'th','zh-hans':'zh-Hans'})[location.pathname.split('/')[1]]||'en';
let initialLanguage=pageLanguage;
setLanguage(initialLanguage,false);
document.querySelectorAll('[data-language]').forEach(link=>link.addEventListener('click',()=>{try{localStorage.setItem('fxxkup-language',link.dataset.language)}catch{}}));
document.addEventListener('keydown',event=>{const menu=document.querySelector('.language-menu');if(event.key==='Escape'&&menu.open){menu.open=false;menu.querySelector('summary').focus();}});
document.addEventListener('click',event=>{const menu=document.querySelector('.language-menu');if(!menu.contains(event.target))menu.open=false;});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button?'true':'false')});document.querySelectorAll('[data-category]').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter)}));
document.getElementById('copy-address').addEventListener('click',async()=>{const address='〒064-0805 北海道札幌市中央区南5条西5丁目21−3 第3旭観光ビル6F Rock Bar FxxK Up';const status=copyStatus;try{await navigator.clipboard.writeText(address);status.textContent=language==='ja'?'住所をコピーしました。タクシーの運転手さんにお見せください。':language==='ko'?'주소를 복사했습니다. 택시 기사님께 보여 주세요.':language==='th'?'คัดลอกที่อยู่แล้ว แสดงให้คนขับแท็กซี่ได้เลย':language==='zh-Hans'?'地址已复制，可以出示给出租车司机。':'Address copied. Show it to your taxi driver.'}catch{status.textContent=address}});
